def parse_expansion():
    result=[]
    seen=set()
    for raw in RAW_THEMES:
        group={}
        for row in raw.splitlines():
            jp, reading, meaning, emoji = row.split("|")
            if jp in seen:
                raise ValueError(f"Repeated word in expansion: {jp}")
            seen.add(jp)
            group[jp]={'value':jp,'reading':reading,'meaning':meaning,'emoji':emoji,
                       'script':'katakana' if any('ァ' <= ch <= 'ヶ' for ch in jp) else 'hiragana'}
        result.append(group)
    return result

EXPANSION = parse_expansion()
